     * @param StringOffset
     * @return void
     */
    public static function addPRODUCER_ID(FlatBufferBuilder $builder, $PRODUCER_ID)
    {
        $builder->addOffsetX(21, $PRODUCER_ID, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addSIGNATURE(FlatBufferBuilder $builder, $SIGNATURE)
    {
        $builder->addOffsetX(22, $SIGNATURE, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param array offset array
     * @return int vector offset
     */
    public static function createSIGNATUREVector(FlatBufferBuilder $builder, array $data)
    {
        $builder->startVector(1, count($data), 1);
        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putByte($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startSIGNATUREVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(1, $numElems, 1);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addCANONICAL_JSON_SIGNATURE(FlatBufferBuilder $builder, $CANONICAL_JSON_SIGNATURE)
    {
        $builder->addOffsetX(23, $CANONICAL_JSON_SIGNATURE, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param array offset array
     * @return int vector offset
     */
    public static function createCANONICAL_JSON_SIGNATUREVector(FlatBufferBuilder $builder, array $data)
    {
        $builder->startVector(1, count($data), 1);
        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putByte($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startCANONICAL_JSON_SIGNATUREVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(1, $numElems, 1);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endEPF(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // EPF_ID
        $builder->required($o, 20);  // VALUE_UNITS
        $builder->required($o, 24);  // SAMPLE_EPOCHS
        $builder->required($o, 26);  // SAMPLE_VALUES
        $builder->required($o, 28);  // SAMPLE_LIMIT_VALUES
        $builder->required($o, 30);  // SAMPLE_MARGIN_DB
        $builder->required($o, 32);  // SAMPLE_EXCEEDS_LIMIT
        $builder->required($o, 36);  // CDF_VALUES
        $builder->required($o, 38);  // CDF_PERCENT_TIME_EXCEEDED
        $builder->required($o, 40);  // VERDICT
        $builder->required($o, 42);  // PROVENANCE
        $builder->required($o, 46);  // PRODUCER_ID
        $builder->required($o, 48);  // SIGNATURE
        $builder->required($o, 50);  // CANONICAL_JSON_SIGNATURE
        return $o;
    }

    public static function finishEPFBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$EPF");
    }
}
